steps.script:
function transform(ctx) {
  var u = ctx.vars.portal_url || "";
  if (!u || u.indexOf("?") < 0) throw new Error("未能获取门户跳转地址（Location），请核对本校门户地址后把地址写进本步骤脚本");
  var q = u.slice(u.indexOf("?") + 1);
  var host = u.split("/")[2];
  // login.go L26-27：redirectUrl.Query().Encode() 会把参数按 key 字母序排序
  var pairs = q.split("&").map(function (p) { return p.split("="); });
  pairs.sort(function (a, b) { return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0; });
  var qs = pairs.map(function (p) { return p.join("="); }).join("&");
  var service = "默认"; // login.go L24：固定 service=%E9%BB%98%E8%AE%A4，运营商由 IP 段检测决定，不经 service
  return { portal_host: host, qse: url_encode(qs), eu: url_encode(ctx.username || ""), ep: url_encode(ctx.password || ""), es: url_encode(url_encode(service)) };
}
